const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const expected=JSON.parse(fs.readFileSync(path.join(__dirname,'public-expected-files.json'))),base=process.env.TAILOR_PUBLIC_BASE||'https://haihao0307.github.io/guilin-dem-pipeline',out='catalogue-public-hash';fs.mkdirSync(out,{recursive:true});
const report={base,productFileCount:expected.productFileCount,protectedOldFileCount:expected.protectedOldFileCount,files:[],startedAt:new Date().toISOString()};let cursor=0;
async function inspect(row){let result;for(let attempt=1;attempt<=3;attempt++){const started=Date.now();try{const response=await fetch(base+'/'+row.path,{signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error('HTTP '+response.status);const bytes=Buffer.from(await response.arrayBuffer()),sha256=crypto.createHash('sha256').update(bytes).digest('hex'),gitSha=crypto.createHash('sha1').update(Buffer.from('blob '+bytes.length+'\0')).update(bytes).digest('hex');result={path:row.path,bytes:bytes.length,gitSha,sha256,attempt,elapsedMs:Date.now()-started,pass:bytes.length===row.bytes&&gitSha===row.gitSha&&(!row.sha256||sha256===row.sha256)};if(!result.pass)result.error='Exact expected bytes or hash mismatch';break;}catch(error){result={path:row.path,attempt,elapsedMs:Date.now()-started,pass:false,error:error.message};if(attempt<3)await new Promise(r=>setTimeout(r,1000*attempt));}}return result;}
async function worker(){while(cursor<expected.files.length){const row=expected.files[cursor++];report.files.push(await inspect(row));}}
(async()=>{await Promise.all(Array.from({length:4},worker));report.files.sort((a,b)=>a.path.localeCompare(b.path));report.finishedAt=new Date().toISOString();report.passed=report.files.filter(r=>r.pass).length;report.total=expected.files.length;report.success=report.passed===report.total;fs.writeFileSync(path.join(out,'result.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({success:report.success,passed:report.passed,total:report.total,failed:report.files.filter(r=>!r.pass)}));if(!report.success)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
